const body = $('Webhook').item.json.body;
const brandItem = $('Lookup Brand Profile').all()[0];
const brand = brandItem ? brandItem.json : {};

const brandName = brand.brand_name || body.branch || 'the brand';
const tone = body.tone || brand.default_tone || 'friendly';
const pron = brand.pronunciation_guide || '';
const aspect = body.aspect_ratio || '1:1';
const platform = body.platform || 'general';
const segment = body.target_segment || 'general audience';
const styleNotes = body.style_notes || '';
const topic = body.topic || '';
const slideCount = Math.max(3, Math.min(7, Number(body.slide_count) || 5));
const revisionNotes = body.revision_notes || '';

const styleBlock = 'Style: consistent ' + tone + ' brand photography/illustration style for ' + brandName + '. Identical colour palette, identical lighting, identical composition rules (subject centred, ' + aspect + ' aspect ratio, generous negative space reserved for on-slide text) across every slide in the set. No watermarks, no logos, no stock-photo badges.';

const shape = { caption: 'ready-to-publish social caption for the whole carousel, 1-3 sentences, up to 3 hashtags', slides: [{ title: 'short on-slide title, max 8 words', body: 'one supporting sentence, max 18 words', image_prompt: 'description of the still image for this slide, no on-image body copy other than the title' }] };

let plan_prompt = 'You are planning a ' + slideCount + '-slide social media carousel. Brand: ' + brandName + '. Topic: ' + topic + '. Audience: ' + segment + '. Tone: ' + tone + '. Platform: ' + platform + '. Pronunciation and brand rules: ' + pron + '. ' + (styleNotes ? ('Style notes: ' + styleNotes + '. ') : '') + 'Slide 1 MUST be a scroll-stopping hook. The LAST slide (slide ' + slideCount + ') MUST be a clear call to action. The slides in between build out the idea one point at a time. Return ONLY valid JSON, no markdown fences, no commentary, in exactly this shape: ' + JSON.stringify(shape) + '. The slides array must contain exactly ' + slideCount + ' items.';
if (revisionNotes) {
  plan_prompt += ' REVISION REQUEST - the previous attempt was rejected. Apply this feedback: ' + revisionNotes;
}

return [{ json: {
  plan_prompt,
  style_block: styleBlock,
  brand_name: brandName,
  tone,
  aspect_ratio: aspect,
  platform,
  slide_count: slideCount,
  job_id: body.job_id,
  branch: body.branch,
  revision_notes: revisionNotes,
} }];

const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] && $json.candidates[0].content.parts[0].text) || '';
const prep = $('Prepare Slide Plan').item.json;
const revisionNotes = prep.revision_notes || '';

function extractJson(text) {
  try { return JSON.parse(text); } catch (e) {}
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    try { return JSON.parse(match[0]); } catch (e) {}
  }
  return null;
}

let plan = extractJson(raw);
if (!plan || !Array.isArray(plan.slides) || plan.slides.length === 0) {
  plan = {
    caption: prep.brand_name + ': ' + prep.tone + ' update.',
    slides: [{ title: prep.brand_name, body: raw.slice(0, 140) || 'See more.', image_prompt: 'A clean on-brand marketing photo for ' + prep.brand_name + '.' }],
  };
}

let slides = plan.slides.slice(0, prep.slide_count);
if (slides.length === 0) {
  throw new Error('Slide plan produced zero usable slides.');
}

slides = slides.map(function (s) {
  return {
    title: (s.title || '').toString(),
    body: (s.body || '').toString(),
    image_prompt: (s.image_prompt || 'A clean on-brand marketing photo.').toString() + ' ' + prep.style_block + (revisionNotes ? ' REVISION REQUEST - the previous attempt was rejected. Apply this feedback: ' + revisionNotes : ''),
  };
});

return [{ json: {
  caption: (plan.caption || (prep.brand_name + ' - new today.')).toString(),
  slides,
  job_id: prep.job_id,
  branch: prep.branch,
  aspect_ratio: prep.aspect_ratio,
  revision_notes: revisionNotes,
} }];

const plan = $('Parse Slide Plan').item.json;
const slides = Array.isArray(plan.slides) ? plan.slides : [];
return slides.map(function (s, i) {
  return { json: {
    job_id: plan.job_id,
    branch: plan.branch,
    aspect_ratio: plan.aspect_ratio,
    slide_index: i + 1,
    slide_count: slides.length,
    title: s.title,
    body: s.body,
    image_prompt: s.image_prompt,
  } };
});

const cands = $json.candidates || [];
let b64 = null;
let mime = 'image/png';

for (const c of cands) {
  const parts = (c.content && c.content.parts) || [];
  for (const p of parts) {
    const inline = p.inlineData || p.inline_data;
    if (inline && inline.data) {
      b64 = inline.data;
      mime = inline.mimeType || inline.mime_type || mime;
      break;
    }
  }
  if (b64) break;
}

if (!b64) {
  throw new Error('No image returned by Gemini for slide ' + $('Split Slides').item.json.slide_index + '. Raw: ' + JSON.stringify($json).slice(0, 300));
}

const jobId = $('Split Slides').item.json.job_id;
const slideIndex = $('Split Slides').item.json.slide_index;
const ext = mime.includes('jpeg') ? 'jpg' : 'png';
const rand = Math.random().toString(36).slice(2, 8);
const path = 'static-ads/' + jobId + '/slide-' + slideIndex + '-' + rand + '.' + ext;

return {
  json: { storage_path: path, mime, slide_index: slideIndex },
  binary: {
    data: {
      data: b64,
      mimeType: mime,
      fileName: 'slide-' + slideIndex + '-' + rand + '.' + ext,
    },
  },
};

const uploaded = $input.all();
const meta = $('Extract Slide Image').all();
const plan = $('Parse Slide Plan').item.json;

if (uploaded.length !== plan.slides.length || meta.length !== plan.slides.length) {
  throw new Error('Expected ' + plan.slides.length + ' carousel slides, got ' + uploaded.length + ' uploads / ' + meta.length + ' extracted - one or more slides failed.');
}

const BASE = 'https://horvjqqifgrzxesuxtfm.supabase.co/storage/v1/object/public/episode-assets/';

const media_urls = meta
  .slice()
  .sort(function (a, b) { return a.json.slide_index - b.json.slide_index; })
  .map(function (m) { return BASE + m.json.storage_path; });

return [{ json: { media_urls, frame_url: media_urls[0], job_id: plan.job_id } }];
